// System Warden: Health Analyzer
// Monitors 8 LNL workflows for errors and heartbeat freshness
// v2: Added 6-hour cooldown to suppress repeat alerts

const MONITORED = [
  { id: 'DE81QfyyeSOaA778', name: 'Lead Gen Agent', type: 'schedule', maxStaleMin: 180 },
  { id: 'lhytfLiKaudl5vKa', name: 'Cold Outreach Agent', type: 'schedule', maxStaleMin: 180 },
  { id: 'jmqcSnF8v4lJWHIf', name: 'Personal Assistant', type: 'webhook', maxStaleMin: 0 },
  { id: 'm475ggRUeYhCBTOr', name: 'Inbound Processor', type: 'webhook', maxStaleMin: 0 },
  { id: '5kKTxZAh3ZJaZHeP', name: 'Booking-to-Pipeline', type: 'webhook', maxStaleMin: 0 },
  { id: 'lc1kXeqQ9eOJaQ7X', name: 'Concierge Agent', type: 'webhook', maxStaleMin: 0 },
  { id: 'Xuz30f7XIKUHqjJV', name: 'Intelligence Engine', type: 'schedule', maxStaleMin: 30 }
];

const COOLDOWN_HOURS = 6;

const executions = $input.all().map(i => i.json);
const now = new Date();
const issues = [];
const report = [];

// Cooldown: read last alerted times from static data (persisted across runs)
let lastAlerted = {};
try {
  const stored = $getWorkflowStaticData('global');
  if (stored.lastAlerted) lastAlerted = JSON.parse(stored.lastAlerted);
} catch(e) { /* first run */ }

function shouldAlert(key) {
  const last = lastAlerted[key];
  if (!last) return true;
  const hoursSince = (now - new Date(last)) / 3600000;
  return hoursSince >= COOLDOWN_HOURS;
}

function markAlerted(key) {
  lastAlerted[key] = now.toISOString();
}

const byWf = {};
for (const e of executions) {
  const wid = e.workflowId;
  if (!wid) continue;
  if (!byWf[wid]) byWf[wid] = [];
  byWf[wid].push(e);
}

let suppressedCount = 0;

for (const wf of MONITORED) {
  const execs = byWf[wf.id] || [];
  const errors = execs.filter(e => e.status === 'error');
  const successes = execs.filter(e => e.status === 'success');

  if (errors.length > 0) {
    const key = wf.id + ':ERROR';
    if (shouldAlert(key)) {
      issues.push({
        workflow: wf.name, id: wf.id, type: 'ERROR', severity: 'HIGH',
        detail: errors.length + ' error(s). Latest: ' + (errors[0].stoppedAt || 'unknown'),
        executionId: errors[0].id
      });
      markAlerted(key);
    } else { suppressedCount++; }
  }

  if (wf.type === 'schedule' && wf.maxStaleMin > 0) {
    if (successes.length > 0) {
      const last = new Date(successes[0].stoppedAt || successes[0].startedAt);
      const mins = (now - last) / 60000;
      if (mins > wf.maxStaleMin) {
        const key = wf.id + ':STALE';
        if (shouldAlert(key)) {
          issues.push({
            workflow: wf.name, id: wf.id, type: 'STALE', severity: 'MEDIUM',
            detail: 'No success in ' + Math.round(mins) + 'min (expected every ' + wf.maxStaleMin + 'min)'
          });
          markAlerted(key);
        } else { suppressedCount++; }
      }
    } else if (execs.length === 0) {
      const key = wf.id + ':NO_DATA';
      if (shouldAlert(key)) {
        issues.push({
          workflow: wf.name, id: wf.id, type: 'NO_DATA', severity: 'LOW',
          detail: 'No recent executions found'
        });
        markAlerted(key);
      } else { suppressedCount++; }
    }
  }

  report.push({
    name: wf.name,
    status: errors.length > 0 ? 'ERROR' : 'OK',
    errors: errors.length,
    successes: successes.length,
    lastExec: execs.length > 0 ? (execs[0].stoppedAt || execs[0].startedAt || 'unknown') : 'none'
  });
}

// Persist cooldown state
try {
  const stored = $getWorkflowStaticData('global');
  stored.lastAlerted = JSON.stringify(lastAlerted);
} catch(e) { /* static data not available */ }

const status = issues.some(i => i.severity === 'HIGH') ? 'CRITICAL' :
               issues.length > 0 ? 'WARNING' : 'HEALTHY';

return [{ json: { timestamp: now.toISOString(), overallStatus: status, issueCount: issues.length, suppressedCount, issues, report } }];

// Format health alert for email + sheet logging
// v4: Actionable subjects and direct n8n links per failing workflow
const d = $input.item.json;
const issues = d.issues || [];

// Build actionable subject with failing workflow names
const failingNames = issues.filter(i => i.severity === 'HIGH').map(i => i.workflow);
let subject = '';
if (failingNames.length > 0) subject = failingNames.join(', ') + ' failing - action needed';
else if (issues.length > 0) subject = issues.length + ' warning(s) - System Warden check';
else subject = 'All systems healthy - System Warden check';

const statusColor = d.overallStatus === 'CRITICAL' ? '#dc3545' : d.overallStatus === 'WARNING' ? '#ffc107' : '#28a745';

let html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">';
html += '<h2 style="color:' + statusColor + '">' + d.overallStatus + '</h2>';

if (issues.length > 0) {
  html += '<h3>What needs attention</h3>';
  for (const i of issues) {
    const sevColor = i.severity === 'HIGH' ? '#dc3545' : i.severity === 'MEDIUM' ? '#ffc107' : '#6c757d';
    const link = 'https://n8n.srv1244684.hstgr.cloud/workflow/' + i.id;
    html += '<div style="border-left:4px solid ' + sevColor + ';padding:10px 15px;margin:10px 0;background:#f8f9fa">';
    html += '<strong>' + i.workflow + '</strong> - ' + i.type + '<br>';
    html += '<span style="color:#555">' + i.detail + '</span><br>';
    if (i.executionId) {
      html += '<a href="' + link + '/executions/' + i.executionId + '" style="color:#007bff">View failed execution</a>';
    } else {
      html += '<a href="' + link + '" style="color:#007bff">Open workflow</a>';
    }
    html += '</div>';
  }
}

html += '<h3>All Workflows</h3><table style="border-collapse:collapse;width:100%">';
html += '<tr style="background:#f8f9fa"><th style="border:1px solid #dee2e6;padding:6px;text-align:left">Workflow</th><th style="border:1px solid #dee2e6;padding:6px;text-align:left">Status</th><th style="border:1px solid #dee2e6;padding:6px;text-align:left">Errors</th></tr>';
for (const r of (d.report || [])) {
  const rowColor = r.status === 'ERROR' ? '#fff3f3' : '#f3fff3';
  html += '<tr style="background:' + rowColor + '">';
  html += '<td style="border:1px solid #dee2e6;padding:6px">' + r.name + '</td>';
  html += '<td style="border:1px solid #dee2e6;padding:6px">' + r.status + '</td>';
  html += '<td style="border:1px solid #dee2e6;padding:6px">' + r.errors + '</td></tr>';
}
html += '</table>';
if (d.suppressedCount > 0) {
  html += '<p style="color:#6c757d;font-size:12px">' + d.suppressedCount + ' repeat alert(s) suppressed by 6-hour cooldown.</p>';
}
html += '</div>';

const issueSummary = issues.map(i => '[' + i.severity + '] ' + i.workflow + ': ' + i.type).join('; ');

return {
  json: {
    subject, htmlBody: html,
    'Date': d.timestamp,
    'Action': 'System Warden Alert - ' + d.overallStatus,
    'Records Affected': d.issueCount,
    'Details': issueSummary || 'No issues',
    'System Status': d.overallStatus
  }
};

// Prepare all-clear log entry
// v3: Use $input.item.json (not $json) for Code node v2 compatibility
const d = $input.item.json;
const now = new Date().toISOString();

return {
  json: {
    'Date': d.timestamp || now,
    'Action': 'System Warden Health Check',
    'Records Affected': 0,
    'Details': 'All ' + (d.report || []).length + ' monitored workflows healthy',
    'System Status': 'HEALTHY'
  }
};

// Format error details for email + sheet logging
// v4: Added 6-hour cooldown per workflow to prevent email spam
const err = $input.item.json;
const now = new Date();
const nowISO = now.toISOString();

const wfName = (err.workflow && err.workflow.name) || 'Unknown Workflow';
const wfId = (err.workflow && err.workflow.id) || 'unknown';
const errMsg = (err.execution && err.execution.error && err.execution.error.message) || 'No error message';
const execId = (err.execution && err.execution.id) || 'unknown';
const failedNode = (err.execution && err.execution.lastNodeExecuted) || 'Unknown Node';
const reviewUrl = 'https://n8n.srv1244684.hstgr.cloud/workflow/' + wfId + '/executions/' + execId;

// 6-hour cooldown per workflow to prevent spam
const COOLDOWN_HOURS = 6;
let lastAlerted = {};
try {
  const stored = $getWorkflowStaticData('global');
  if (stored.errorLastAlerted) lastAlerted = JSON.parse(stored.errorLastAlerted);
} catch(e) {}

const lastTime = lastAlerted[wfId];
const hoursSince = lastTime ? (now - new Date(lastTime)) / 3600000 : 999;

if (hoursSince < COOLDOWN_HOURS) {
  // Suppressed: still log to sheet but skip email
  return {
    json: {
      subject: null, htmlBody: null, _suppressed: true,
      'Date': nowISO,
      'Action': 'Workflow Error (suppressed - cooldown)',
      'Records Affected': 1,
      'Details': wfName + ': ' + errMsg + ' (Node: ' + failedNode + ')',
      'System Status': 'ERROR - ' + wfName + ' (suppressed)'
    }
  };
}

// Mark alerted
lastAlerted[wfId] = nowISO;
try {
  const stored = $getWorkflowStaticData('global');
  stored.errorLastAlerted = JSON.stringify(lastAlerted);
} catch(e) {}

const subject = '[ERROR] ' + wfName + ' failed at ' + failedNode;

let html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">';
html += '<h2 style="color:#dc3545">' + wfName + ' Error</h2>';
html += '<table style="border-collapse:collapse;width:100%">';
html += '<tr><td style="padding:8px;border:1px solid #dee2e6;background:#f8f9fa"><strong>What Failed</strong></td><td style="padding:8px;border:1px solid #dee2e6">' + failedNode + '</td></tr>';
html += '<tr><td style="padding:8px;border:1px solid #dee2e6;background:#f8f9fa"><strong>Error</strong></td><td style="padding:8px;border:1px solid #dee2e6;color:#dc3545">' + errMsg + '</td></tr>';
html += '<tr><td style="padding:8px;border:1px solid #dee2e6;background:#f8f9fa"><strong>Workflow</strong></td><td style="padding:8px;border:1px solid #dee2e6">' + wfName + '</td></tr>';
html += '<tr><td style="padding:8px;border:1px solid #dee2e6;background:#f8f9fa"><strong>Time</strong></td><td style="padding:8px;border:1px solid #dee2e6">' + nowISO + '</td></tr>';
html += '</table>';
html += '<p style="margin-top:16px"><a href="' + reviewUrl + '" style="background:#007bff;color:white;padding:10px 20px;text-decoration:none;display:inline-block">Review in n8n</a></p>';
html += '<p style="color:#6c757d;font-size:12px;margin-top:20px">Next alert for this workflow suppressed for 6 hours.</p>';
html += '</div>';

return {
  json: {
    subject, htmlBody: html, _suppressed: false,
    'Date': nowISO,
    'Action': 'Workflow Error Caught',
    'Records Affected': 1,
    'Details': wfName + ': ' + errMsg + ' (Node: ' + failedNode + ')',
    'System Status': 'ERROR - ' + wfName
  }
};
